-- Proposed PostgreSQL schema for the server-backed research prototype.
-- UUIDs are generated by the application. This file is not used by the browser demo.
CREATE TABLE users (
  id uuid PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now(),
  consent_version text,
  consented_at timestamptz
);
CREATE TABLE subjects (
  id text PRIMARY KEY,
  name text NOT NULL
);
CREATE TABLE topics (
  id text PRIMARY KEY,
  subject_id text NOT NULL REFERENCES subjects(id),
  title text NOT NULL,
  unit text NOT NULL,
  difficulty smallint NOT NULL CHECK (difficulty BETWEEN 1 AND 5),
  estimated_minutes integer NOT NULL CHECK (estimated_minutes > 0),
  curriculum_version text NOT NULL,
  is_active boolean NOT NULL DEFAULT true
);
CREATE TABLE topic_prerequisites (
  topic_id text NOT NULL REFERENCES topics(id),
  prerequisite_topic_id text NOT NULL REFERENCES topics(id),
  PRIMARY KEY (topic_id, prerequisite_topic_id),
  CHECK (topic_id <> prerequisite_topic_id)
);
-- A database constraint cannot reject longer graph cycles; validate the full graph before publishing a curriculum version.
CREATE TABLE learning_objectives (
  id text PRIMARY KEY,
  topic_id text NOT NULL REFERENCES topics(id),
  description text NOT NULL,
  objective_version text NOT NULL
);
CREATE TABLE study_activities (
  id text PRIMARY KEY,
  topic_id text NOT NULL REFERENCES topics(id),
  activity_type text NOT NULL,
  instructions text NOT NULL,
  version text NOT NULL
);
CREATE TABLE assessment_items (
  id uuid PRIMARY KEY,
  objective_id text NOT NULL REFERENCES learning_objectives(id),
  item_version text NOT NULL,
  difficulty numeric(5,3),
  item_payload jsonb NOT NULL,
  answer_key jsonb NOT NULL,
  is_active boolean NOT NULL DEFAULT true
);
CREATE TABLE cognitive_sessions (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id),
  battery_version text NOT NULL,
  started_at timestamptz NOT NULL,
  completed_at timestamptz,
  device_info jsonb
);
CREATE TABLE cognitive_trials (
  id uuid PRIMARY KEY,
  session_id uuid NOT NULL REFERENCES cognitive_sessions(id),
  task_type text NOT NULL,
  task_version text NOT NULL,
  trial_index integer NOT NULL CHECK (trial_index >= 0),
  stimulus jsonb NOT NULL,
  response jsonb,
  is_correct boolean,
  response_time_ms integer CHECK (response_time_ms >= 0),
  presented_at timestamptz NOT NULL,
  responded_at timestamptz,
  UNIQUE (session_id, task_type, trial_index)
);
CREATE TABLE state_questionnaires (
  id uuid PRIMARY KEY,
  cognitive_session_id uuid NOT NULL UNIQUE REFERENCES cognitive_sessions(id),
  questionnaire_version text NOT NULL,
  responses jsonb NOT NULL,
  completed_at timestamptz NOT NULL
);
CREATE TABLE student_topic_mastery (
  user_id uuid NOT NULL REFERENCES users(id),
  topic_id text NOT NULL REFERENCES topics(id),
  estimated_mastery numeric(5,4) NOT NULL CHECK (estimated_mastery BETWEEN 0 AND 1),
  uncertainty numeric(5,4) NOT NULL CHECK (uncertainty BETWEEN 0 AND 1),
  estimator_version text NOT NULL,
  updated_at timestamptz NOT NULL,
  PRIMARY KEY (user_id, topic_id)
);
CREATE TABLE study_sessions (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id),
  topic_id text NOT NULL REFERENCES topics(id),
  activity_id text NOT NULL REFERENCES study_activities(id),
  started_at timestamptz NOT NULL,
  completed_at timestamptz,
  planned_minutes integer NOT NULL CHECK (planned_minutes > 0),
  actual_seconds integer CHECK (actual_seconds >= 0),
  interruption_count integer CHECK (interruption_count >= 0)
);
CREATE TABLE knowledge_assessments (
  id uuid PRIMARY KEY,
  study_session_id uuid NOT NULL REFERENCES study_sessions(id),
  assessment_type text NOT NULL CHECK (assessment_type IN ('pre','immediate','delayed')),
  form_version text NOT NULL,
  completed_at timestamptz,
  due_at timestamptz
);
CREATE TABLE knowledge_responses (
  id uuid PRIMARY KEY,
  assessment_id uuid NOT NULL REFERENCES knowledge_assessments(id),
  item_id uuid NOT NULL REFERENCES assessment_items(id),
  response jsonb NOT NULL,
  is_correct boolean,
  response_time_ms integer CHECK (response_time_ms >= 0),
  answered_at timestamptz NOT NULL,
  UNIQUE (assessment_id, item_id)
);
CREATE TABLE recommendations (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id),
  cognitive_session_id uuid REFERENCES cognitive_sessions(id),
  topic_id text NOT NULL REFERENCES topics(id),
  activity_id text REFERENCES study_activities(id),
  model_version text NOT NULL,
  policy text NOT NULL,
  predicted_gain numeric(7,4),
  selection_probability numeric(7,6) CHECK (selection_probability BETWEEN 0 AND 1),
  candidate_set jsonb NOT NULL,
  explanation jsonb NOT NULL,
  generated_at timestamptz NOT NULL
);
CREATE TABLE experiment_assignments (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id),
  study_session_id uuid UNIQUE REFERENCES study_sessions(id),
  recommendation_id uuid REFERENCES recommendations(id),
  policy text NOT NULL,
  assignment_probability numeric(7,6) NOT NULL CHECK (assignment_probability > 0 AND assignment_probability <= 1),
  randomization_version text NOT NULL,
  assigned_at timestamptz NOT NULL
);
CREATE INDEX cognitive_sessions_user_started_idx ON cognitive_sessions(user_id, started_at DESC);
CREATE INDEX study_sessions_user_started_idx ON study_sessions(user_id, started_at DESC);
CREATE INDEX knowledge_assessments_due_idx ON knowledge_assessments(due_at) WHERE assessment_type='delayed' AND completed_at IS NULL;
CREATE INDEX recommendations_user_generated_idx ON recommendations(user_id, generated_at DESC);
